SELECT COUNT(DISTINCT a.`id`) FROM @{DATA_SCHEMA}.`scence_ipobject_detail` a LEFT JOIN `cmdb_resourcecenter_resource_account` b ON b.`resource_id` = a.`id` LEFT JOIN `cmdb_resourcecenter_account` c ON c.`id` = b.`account_id` LEFT JOIN `cmdb_resourcecenter_resource_tag` d ON d.`resource_id` = a.`id` left join autoexec_job_resource_inspect ajri on ajri.resource_id=a.id left join autoexec_job_phase_node ajpn on ajpn.job_phase_id =ajri.phase_id AND ajpn.resource_id = a.id
LEFT JOIN cmdb_cientity_group ccg ON ccg.cientity_id = a.id LEFT JOIN cmdb_group_auth cga ON ccg.group_id = cga.group_id
LEFT JOIN cmdb_group cg ON cga.group_id = cg.id AND cg.type in ('autoexec')
LEFT JOIN cmdb_group cg ON cga.group_id = cg.id AND cg.type in ('readonly','maintain','autoexec')
JOIN fulltextindex_field_cmdb ffc ON ffc.target_id = a.id AND ffc.target_field IN (#{nameFieldAttrId}, #{ipFieldAttrId}) JOIN fulltextindex_word fw ON ffc.word_id = fw.id
JOIN fulltextindex_field_cmdb ffc2 ON ffc2.target_id = a.id
AND ffc2.target_field = #{nameFieldAttrId}
AND ffc2.target_field = #{ipFieldAttrId}
JOIN fulltextindex_word fw2 ON ffc2.word_id = fw2.id
${conditionWhereSql}
${preCondition.conditionWhereSql}

